#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <nb.h>

/* Physical constants in SI / brick-system units:
   1 stud pitch = 8.0 mm = 0.008 m
   1 brick height = 9.6 mm = 0.0096 m
   Clutch power per stud = 2.2 N axial pull-out
   Mass per 1x1 brick voxel = 0.32 g */
#define PITCH_M      0.008
#define BRICK_H_M    0.0096
#define CLUTCH_N     2.20
#define VOXEL_MASS_G 0.32
#define GRAVITY      9.81

struct BrickNode {
  int id;
  int x, y, z;
  int sx, sz;
  int is_pier;
  double stress_ratio; /* max stud utilization on this brick (1.0 = 100% clutch limit) */
  double Moment_Nm;
  double defl_mm;      /* vertical deflection at brick centroid */
  double slope_rad;
};

struct StudEdge {
  int lower_id;
  int upper_id;
  int stud_x;
  int layer_y;
  int num_studs;       /* 2 studs across width (2x4 brick) * overlap length */
  double pull_N;       /* tensile force per stud */
  double util;         /* pull_N / CLUTCH_N */
};

static struct BrickNode nodes[256];
static int num_nodes = 0;
static struct StudEdge edges[512];
static int num_edges = 0;

int main(void) {
  int span = (int)nb_get_int("bridge_span", 16);
  int layers = (int)nb_get_int("bridge_layers", 4);
  int overlap = (int)nb_get_int("bridge_overlap", 2);
  double tip_load_g = nb_get_number("tip_load_g", 220.0);

  if (span < 8) span = 8;
  if (span > 20) span = 20;
  if (layers < 2) layers = 2;
  if (layers > 6) layers = 6;
  if (overlap < 1) overlap = 1;
  if (overlap > 2) overlap = 2;

  int pier_w = 4;
  int total_len = pier_w + span;

  /* 1. Generate Pier Base (x = 0..3, y = 0..2) */
  for (int y = 0; y < 3; y++) {
    nodes[num_nodes] = (struct BrickNode){ num_nodes, 0, y, 0, 4, 2, 1, 0, 0, 0, 0 };
    num_nodes++;
  }

  /* 2. Generate Cantilever Beam (y = 3 .. 3 + layers - 1) using 2x4 bricks
     with staggered horizontal phase per layer based on overlap (2 or 1 stud) */
  for (int ly = 0; ly < layers; ly++) {
    int y = 3 + ly;
    int offset = (ly & 1) ? (4 - overlap) : 0;
    int x = 0;
    if (offset > 0) {
      /* Starter brick at root pier */
      nodes[num_nodes] = (struct BrickNode){ num_nodes, 0, y, 0, offset, 2, 0, 0, 0, 0, 0 };
      num_nodes++;
      x = offset;
    }
    while (x < total_len) {
      int rem = total_len - x;
      int bw = rem >= 4 ? 4 : rem;
      int is_p = (x + bw <= pier_w) ? 1 : 0;
      nodes[num_nodes] = (struct BrickNode){ num_nodes, x, y, 0, bw, 2, is_p, 0, 0, 0, 0 };
      num_nodes++;
      x += bw;
    }
  }

  /* 3. Build Stud-to-Tube Connectivity Graph between layer y and y+1 */
  for (int i = 0; i < num_nodes; i++) {
    for (int j = 0; j < num_nodes; j++) {
      if (nodes[j].y != nodes[i].y + 1) continue;
      int x0 = nodes[i].x > nodes[j].x ? nodes[i].x : nodes[j].x;
      int x1 = (nodes[i].x + nodes[i].sx) < (nodes[j].x + nodes[j].sx)
               ? (nodes[i].x + nodes[i].sx) : (nodes[j].x + nodes[j].sx);
      if (x1 > x0) {
        int ov_studs = (x1 - x0) * 2; /* 2 studs wide */
        edges[num_edges++] = (struct StudEdge){
          i, j, x0, nodes[j].y, ov_studs, 0.0, 0.0
        };
      }
    }
  }

  /* 4. Solve Cantilever Bending Moment, Stud Pull-Out & Deflection Curve */
  double tip_N = (tip_load_g / 1000.0) * GRAVITY;
  double dead_N_per_stud = (layers * 2 * VOXEL_MASS_G / 1000.0) * GRAVITY;
  double eff_depth_m = (layers - 0.5) * BRICK_H_M;
  /* Overlap factor: 1-stud overlap halves lever arm and concentrates shear */
  double overlap_efficiency = (overlap == 2) ? 1.0 : 0.48;
  /* Effective flexural rigidity EI (N*m^2) of interlocked ABS brick beam */
  double EI = 0.085 * pow((double)layers, 2.7) * overlap_efficiency;

  double max_util = 0.0;
  int max_edge_idx = 0;
  int failed_stud_groups = 0;
  /* Each stud's pull is a straight line in the tip load, (pull per newton) * tip + (pull
     from the beam's own weight), so the largest safe tip load is exact: the smallest
     tip that brings any stud to its clutch limit. */
  double safe_tip_N = 1e9;

  for (int e = 0; e < num_edges; e++) {
    int sx = edges[e].stud_x;
    if (sx < pier_w - 1) continue;
    double dist_from_tip_m = (double)(total_len - sx) * PITCH_M;
    double span_studs_rem = (double)(total_len - sx);
    double M = tip_N * dist_from_tip_m
             + 0.5 * dead_N_per_stud * span_studs_rem * dist_from_tip_m;
    double V = tip_N + dead_N_per_stud * span_studs_rem;

    /* Upper layers experience peak bending tension; mid layers experience horizontal shear */
    int rel_layer = edges[e].layer_y - 3;
    double layer_weight = 0.45 + 0.55 * ((double)rel_layer / (double)(layers > 1 ? layers - 1 : 1));
    double couple_T = (M / (eff_depth_m * overlap_efficiency)) * layer_weight;
    double pull_per_stud = (couple_T + 0.35 * V) / (double)edges[e].num_studs;
    double pull_per_tip_N = ((dist_from_tip_m / (eff_depth_m * overlap_efficiency)) * layer_weight + 0.35)
                            / (double)edges[e].num_studs;
    double pull_dead = pull_per_stud - tip_N * pull_per_tip_N;
    double limit_N = pull_dead >= CLUTCH_N ? 0.0 : (CLUTCH_N - pull_dead) / pull_per_tip_N;
    if (limit_N < safe_tip_N) safe_tip_N = limit_N;

    edges[e].pull_N = pull_per_stud;
    edges[e].util = pull_per_stud / CLUTCH_N;
    if (edges[e].util > max_util) {
      max_util = edges[e].util;
      max_edge_idx = e;
    }
    if (edges[e].util > 1.0) failed_stud_groups++;

    if (edges[e].util > nodes[edges[e].lower_id].stress_ratio)
      nodes[edges[e].lower_id].stress_ratio = edges[e].util;
    if (edges[e].util > nodes[edges[e].upper_id].stress_ratio)
      nodes[edges[e].upper_id].stress_ratio = edges[e].util;
  }

  /* Integrate Euler-Bernoulli cantilever deflection w(x) for each brick */
  double L_m = span * PITCH_M;
  double max_defl_mm = 0.0;
  for (int i = 0; i < num_nodes; i++) {
    double xc = (nodes[i].x + 0.5 * nodes[i].sx) - pier_w;
    if (xc <= 0 || nodes[i].is_pier) {
      nodes[i].defl_mm = 0.0;
      nodes[i].slope_rad = 0.0;
      continue;
    }
    double x_m = xc * PITCH_M;
    if (x_m > L_m) x_m = L_m;
    /* Point-load + uniform dead-weight cantilever deflection formula */
    double w_tip = (tip_N * x_m * x_m * (3.0 * L_m - x_m)) / (6.0 * EI);
    double q = dead_N_per_stud / PITCH_M;
    double w_dead = (q * x_m * x_m * (6.0 * L_m * L_m - 4.0 * L_m * x_m + x_m * x_m)) / (24.0 * EI);
    nodes[i].defl_mm = (w_tip + w_dead) * 1000.0;
    nodes[i].slope_rad = (tip_N * x_m * (2.0 * L_m - x_m)) / (2.0 * EI);
    if (nodes[i].defl_mm > max_defl_mm) max_defl_mm = nodes[i].defl_mm;
  }

  /* Largest tip payload before the first stud passes 100% of its clutch */
  double safe_load_g = safe_tip_N / GRAVITY * 1000.0;

  printf("=== Clutch-Power Structural Graph Analysis ===\n");
  printf("Span: %d studs (%.0f mm) | Depth: %d layers (%.1f mm) | Overlap: %d-stud bond\n",
         span, span * 8.0, layers, layers * 9.6, overlap);
  printf("Graph Topology: %d Bricks (Nodes), %d Stud Couplings (Directed Edges)\n",
         num_nodes, num_edges);
  printf("Tip Payload:    %.0f g (%.2f N) | Max Tip Deflection: %.2f mm\n",
         tip_load_g, tip_N, max_defl_mm);
  printf("Peak Stud Pull: %.2f N / %.2f N capacity (%.1f%% utilization at x=%d, layer=%d)\n",
         edges[max_edge_idx].pull_N, CLUTCH_N, max_util * 100.0,
         edges[max_edge_idx].stud_x, edges[max_edge_idx].layer_y);
  printf("Status:         %s (Estimated max safe payload: %.0f g)\n",
         max_util > 1.0 ? "OVERLOADED - SEAM SEPARATION!" : "STABLE - WITHIN CLUTCH LIMIT",
         safe_load_g);

  static char json[65536];
  int pos = 0;
  pos += snprintf(json + pos, sizeof(json) - pos,
    "{\"span\":%d,\"layers\":%d,\"overlap\":%d,\"tipLoadG\":%.1f,"
    "\"maxUtil\":%.3f,\"maxDeflMm\":%.2f,\"safeLoadG\":%.0f,\"failedEdges\":%d,\"bricks\":[",
    span, layers, overlap, tip_load_g, max_util, max_defl_mm, safe_load_g, failed_stud_groups);

  for (int i = 0; i < num_nodes; i++) {
    pos += snprintf(json + pos, sizeof(json) - pos,
      "%s{\"x\":%d,\"y\":%d,\"sx\":%d,\"sz\":%d,\"pier\":%d,\"u\":%.3f,\"dy\":%.3f,\"rot\":%.4f}",
      i ? "," : "",
      nodes[i].x, nodes[i].y, nodes[i].sx, nodes[i].sz,
      nodes[i].is_pier, nodes[i].stress_ratio, nodes[i].defl_mm, nodes[i].slope_rad);
  }
  pos += snprintf(json + pos, sizeof(json) - pos, "],\"overloaded\":[");
  int first_ov = 1;
  for (int e = 0; e < num_edges; e++) {
    if (edges[e].util >= 0.85) {
      pos += snprintf(json + pos, sizeof(json) - pos,
        "%s{\"x\":%d,\"y\":%d,\"u\":%.2f}",
        first_ov ? "" : ",", edges[e].stud_x, edges[e].layer_y, edges[e].util);
      first_ov = 0;
    }
  }
  pos += snprintf(json + pos, sizeof(json) - pos, "]}");
  nb_set_json("clutch_fem", json);
  return 0;
}

// How hard each brick's busiest studs work, along the beam and layer by layer.
const fem = nb.get('clutch_fem');
if (!fem) return 'Run the C cell first.';

const PIER = 4;                                 // the C cell's pier is 4 studs long
const rows = fem.bricks
  .filter((b) => !b.pier && b.y >= 3)
  .map((b) => ({
    layer: 'layer ' + (b.y - 2),
    from_pier: b.x + b.sx / 2 - PIER,
    load: Math.round(b.u * 1000) / 10,
  }))
  .filter((r) => r.from_pier >= 0)              // the model only loads joints out from the pier
  .sort((a, b) => a.from_pier - b.from_pier);

const peak = rows.reduce((a, b) => (b.load > a.load ? b : a), rows[0]);
console.log(`peak: ${peak.load}% of the clutch limit, ${peak.layer}, ${peak.from_pier} studs from the pier`);
console.log(`bricks with a stud over 100%: ${rows.filter((r) => r.load > 100).length} of ${rows.length}`);

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 260,
  title: "Each brick's busiest studs",
  data: { values: rows },
  encoding: { x: { field: 'from_pier', type: 'quantitative', title: 'studs from the pier' } },
  layer: [
    {
      mark: { type: 'line', point: true, tooltip: true },
      encoding: {
        y: { field: 'load', type: 'quantitative', title: '% of the clutch limit' },
        color: { field: 'layer', type: 'ordinal', title: null, scale: { scheme: 'viridis' } },
      },
    },
    { mark: { type: 'rule', color: '#ef4444', strokeDash: [6, 4] }, encoding: { x: null, y: { datum: 100 } } },
  ],
};
